// Mock 30-day resolved-ticket categories vs playbook index - swap for helpdesk API + KB search
const categories = [
  { category: 'webhook retries failing', count30d: 14, hasPlaybook: false, sampleResolution: 'Usually stale credentials on the destination or a payload over the size limit; fixed by re-auth and batching.' },
  { category: 'SSO/SAML setup', count30d: 11, hasPlaybook: true },
  { category: 'self-host upgrade breaks community nodes', count30d: 8, hasPlaybook: false, sampleResolution: 'Pin node versions before upgrade, re-install community nodes after, verify with a canary workflow.' },
  { category: 'billing proration confusion', count30d: 3, hasPlaybook: false }
];
// Gap = recurring (5+) and undocumented. Below 5, a playbook costs more than it saves.
return categories.filter(c => c.count30d >= 5 && !c.hasPlaybook).map(c => ({ json: c }));

const items = $input.all();
if (!items.length) return [];
let body = 'Playbook gaps this week (recurring 5+ times, no doc). Stubs below are DRAFTS: review, correct, publish.\n';
items.forEach((item, i) => {
  const cat = $('Find Undocumented Recurring Categories').all()[i].json;
  body += '\n======== ' + cat.category + ' (' + cat.count30d + ' tickets/30d) ========\n' + (item.json.output || '') + '\n';
});
body += '\nRule: every resolved escalation becomes documentation. This miner just finds the ones that slipped through.';
return [{ json: { subject: 'Playbook gaps: ' + items.length + ' draft(s) ready for review', body } }];
